// Regression against an independent reference (Swiss Ephemeris, Moshier) and Python zoneinfo.
// Fixture generated by scripts/generate-ephemeris-reference.py. Tolerances documented in QA_REPORT.md.
import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {calculateUtc} from '../src/lib/ephemeris.mjs';
import {natalAngles} from '../src/lib/natal-angles.mjs';
import {resolveLocalTime} from '../src/lib/birth-time.mjs';
const ref = JSON.parse(readFileSync(new URL('./fixtures/ephemeris-reference.json', import.meta.url)));
const arcsec = (a, b) => {const x = Math.abs(a - b) % 360; return Math.min(x, 360 - x) * 3600;};
const TOL = {Sun: 5, Moon: 10, Mercury: 30, Venus: 30, Mars: 30, Jupiter: 30, Saturn: 30, Uranus: 30, Neptune: 30, Pluto: 30};
for (const c of ref.cases) {
  const label = `${c.place} ${c.localDate} ${c.localTime}`;
  test('local time -> UTC matches zoneinfo: ' + label, () => {
    const r = resolveLocalTime(c.localDate, c.localTime, c.zone);
    assert.equal(r.status, 'unique');
    assert.deepEqual(r.candidates, [c.utc]);
  });
  test('planet longitudes within tolerance: ' + label, () => {
    const {longitudes} = calculateUtc(new Date(c.utc));
    for (const [body, tol] of Object.entries(TOL)) assert.ok(arcsec(longitudes[body], c.longitudes[body]) <= tol, `${body} off by ${arcsec(longitudes[body], c.longitudes[body]).toFixed(1)}″`);
  });
  test('ascendant and midheaven within 5″: ' + label, () => {
    const a = natalAngles(new Date(c.utc), c.latitude, c.longitude);
    assert.ok(arcsec(a.ascendant, c.ascendant) <= 5, 'ASC ' + arcsec(a.ascendant, c.ascendant));
    assert.ok(arcsec(a.midheaven, c.midheaven) <= 5, 'MC ' + arcsec(a.midheaven, c.midheaven));
  });
}
